const std = @import("std");

const BitSet = struct {
    bits: u64 = 0,

    fn add(self: *BitSet, idx: u6) void { self.bits |= (@as(u64, 1) << idx); }
    fn remove(self: *BitSet, idx: u6) void { self.bits &= ~(@as(u64, 1) << idx); }
    fn contains(self: BitSet, idx: u6) bool { return (self.bits & (@as(u64, 1) << idx)) != 0; }
    fn unionWith(self: BitSet, other: BitSet) BitSet { return BitSet{ .bits = self.bits | other.bits }; }
    fn intersectWith(self: BitSet, other: BitSet) BitSet { return BitSet{ .bits = self.bits & other.bits }; }
};

pub fn main() !void {
    var a = BitSet{};
    var b = BitSet{};
    a.add(1); a.add(3); a.add(5);
    b.add(3); b.add(5); b.add(7);

    const u = a.unionWith(b);
    const i = a.intersectWith(b);

    std.debug.print("Union has 1: {}\n", .{u.contains(1)});
    std.debug.print("Union has 7: {}\n", .{u.contains(7)});
    std.debug.print("Inter has 3: {}\n", .{i.contains(3)});
    std.debug.print("Inter has 1: {}\n", .{i.contains(1)});
}

